"""Local file storage for uploaded FDR documents. Replace with S3 or GCS later by changing these three functions."""

import os
from pathlib import Path


def upload_dir() -> Path:
    return Path(os.getenv("UPLOAD_DIR", "./uploads"))


def save(key: str, data: bytes) -> None:
    folder = upload_dir()
    folder.mkdir(parents=True, exist_ok=True)
    (folder / key).write_bytes(data)


def path_for(key: str) -> Path:
    # Keys are generated by the server (uuid + extension), never taken from the client.
    return upload_dir() / key
